from pathlib import Path
import re, statistics
for page, title in [(21, 'SummEval'), (22, 'Topical-Chat')]:
 text=Path(f'tmp/pdfs/page-{page:02d}.txt').read_text().split(f'Table {22 if page==21 else 24}:')[0]
