   if len(nums)==10: rows.append((match.group(1),nums))
 print(title, 'rows',len(rows))
 for method in ['G-Eval','SEEval','CheckEval']:
  selected=[row for m,row in rows if m==method]
  print(method, 'averages from per-dimension entries', [round(statistics.mean(statistics.mean(row[k:8:2]) for row in selected),6) for k in [0,1]])
 if page==21:
  g=[v for m,v in rows if m=='G-Eval']
  c=[v for m,v in rows if m=='CheckEval']
  print('Relevance Spearman: CheckEval worse than G-Eval in',sum(a[6]<b[6] for a,b in zip(c,g)),'of',len(c),'models')
